What integer is printed by the following C program?
```c
#include <stdio.h>
int main() {
    int x = 2, res = 0;
    switch (x) {
        case 1: res += 1;
        case 2: res += 2;
        case 3: res += 4; break;
        default: res += 8;
    }
    printf("%d", res);
    return 0;
}
```

What is the output of the following C program?
```c
#include <stdio.h>
void modify(int a[], int n) {
    a[0] += 5;
    a = a + 1;
    a[0] += 10;
}
int main() {
    int arr[3] = {1, 2, 3};
    modify(arr, 3);
    printf("%d %d %d", arr[0], arr[1], arr[2]);
    return 0;
}
```
